const cfg = $input.first().json;
let payload;
if (cfg.custom_json && String(cfg.custom_json).trim()) {
  payload = JSON.parse(cfg.custom_json);
} else {
  const n = Number(cfg.email_number);
  if (!SEEDS[n]) throw new Error('email_number must be 1-10 (got ' + cfg.email_number + ')');
  payload = JSON.parse(JSON.stringify(SEEDS[n]));
}
payload.external_id = 'lab-' + Date.now();
payload.channel = 'learning-lab';
return [{ json: { picked: cfg.custom_json ? 'custom' : 'seed email ' + cfg.email_number, payload } }];
